<script setup lang="ts">
import {ref,reactive,computed,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,l,roles,api,wp,loadWorkspaces,loadData,notify} from '../state'
const route=useRoute(),router=useRouter(),editing=route.path==='/company',fresh=route.query.new==='1',step=ref(editing?2:1),busy=ref(false),error=ref(''),job=ref<any>(null),suggestions=ref<any[]>([]),selected=ref<string[]>([]),sourceStatus=ref('')
const form=reactive({website:'',name:'',industry:'',description:'',activities:'',customers:'',regions:'',scale:'',revenue:'',market_position:'',counterparties:'',competitors:'',exposures:[] as string[],priorities:'',keywords:'',decision_role:'ceo'})
const exposureOptions=computed(()=>[{id:'Credit products / borrowing costs',label:t('Loans & financing','Кредиты и финансирование')},{id:'Foreign-currency revenue or costs',label:t('Foreign currencies','Валютные расчёты')},{id:'Imports / supply-chain dependencies',label:t('Imports & supply chains','Импорт и цепочки поставок')},{id:'Commodity / energy input costs',label:t('Raw materials & energy','Сырьё и энергия')},{id:'Labour costs / staffing',label:t('People & compensation','Персонал и зарплаты')},{id:'Consumer spending / demand',label:t('Consumer demand','Потребительский спрос')},{id:'Data privacy / regulation',label:t('Regulation & data','Регулирование и данные')},{id:'Cloud / technology operating costs',label:t('Technology & cloud costs','Технологии и облачные расходы')}])
const custom=ref(''),created=ref(false)
const split=(s:string)=>s.split(/[,\n]/).map(x=>x.trim()).filter(Boolean)
function fill(p:any){if(!p)return;for(const k of Object.keys(form)){if(k==='exposures')form.exposures=p.exposures||[];else if(k==='description')form.description=l(p.description);else if(k==='decision_role')form.decision_role=state.workspace?.decision_role||'ceo';else (form as any)[k]=Array.isArray(p[k])?p[k].join(', '):p[k]||''}}
onMounted(()=>{if(!fresh&&state.workspace){const p=state.workspace.draft_profile||state.workspace.profile;fill(p);if(p.industry&&p.website&&!editing)step.value=2}})
async function ensureWorkspace(){if((fresh&&!created.value)||!state.workspace){const ws=await api('/workspaces',{method:'POST',body:{name:form.name||t('My company','Моя компания')}});await loadWorkspaces(ws.id);created.value=true}}
async function discover(manual=false){busy.value=true;error.value='';try{if(!/^https?:\/\//.test(form.website))form.website='https://'+form.website;new URL(form.website);await ensureWorkspace();if(manual){await api(wp('/profile'),{method:'PUT',body:{website:form.website}});step.value=2;return}job.value=await api(wp('/profile/discover'),{method:'POST',body:{url:form.website}});state.jobs=[job.value];await waitForJob()}catch(e:any){error.value=e.message}finally{busy.value=false}}
let stop=false
onBeforeUnmount(()=>{stop=true})
async function waitForJob(){while(!stop){await new Promise(r=>setTimeout(r,1500));job.value=await api(wp('/jobs/'+job.value.id));state.jobs=[job.value];if(job.value.status==='completed'){state.workspace=await api(wp(''));fill(state.workspace.draft_profile||state.workspace.profile);form.keywords=((state.workspace.draft_profile||state.workspace.profile).keywords||[]).join(', ');step.value=2;return}if(job.value.status==='failed')throw new Error(job.value.error)}}
function payload(){return{...form,activities:split(form.activities),customers:split(form.customers),regions:split(form.regions),counterparties:split(form.counterparties),competitors:split(form.competitors),priorities:split(form.priorities),keywords:split(form.keywords),exposures:[...new Set([...form.exposures,...split(custom.value)])]}}
async function findSources(){
  busy.value=true
  sourceStatus.value=t('Finding and checking relevant publishers…','Ищем и проверяем подходящие источники…')
  try{
    let j=await api(wp('/source-discovery'),{method:'POST'})
    state.jobs=[j]
    while(!stop&&['queued','running'].includes(j.status)){
      await new Promise(r=>setTimeout(r,1800))
      j=await api(wp('/jobs/'+j.id));state.jobs=[j]
    }
    if(j.status==='failed')throw new Error(j.error)
    suggestions.value=await api(wp('/source-suggestions'))
    selected.value=suggestions.value.slice(0,3).map(x=>x.url)
    sourceStatus.value=suggestions.value.length
      ?t('Publisher websites and actual publications checked for your markets.','Сайты издателей и реальные публикации проверены для ваших рынков.')
      :t('No sufficiently relevant source passed verification. Add sources manually in your workspace.','Подходящих проверенных источников пока нет. Добавьте их вручную в пространстве.')
    if(j.result.coverage_gaps?.length)sourceStatus.value+=' '+t('Coverage still needed: ','Пока не покрыты рынки: ')+j.result.coverage_gaps.join(', ')
  }catch(e:any){sourceStatus.value=e.message}
  finally{busy.value=false}
}
async function review(){if(!form.name||!form.industry||(!form.exposures.length&&!custom.value)){error.value=t('Add the company name, industry and at least one business exposure.','Укажите название, отрасль и хотя бы один фактор влияния на бизнес.');return}busy.value=true;error.value='';try{state.workspace=await api(wp('/profile'),{method:'PUT',body:payload()});if(!form.keywords)form.keywords=[form.name,form.industry].join(', ');suggestions.value=await api(wp('/source-suggestions'));step.value=3;if(!suggestions.value.length)await findSources();else selected.value=suggestions.value.slice(0,3).map(x=>x.url)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function confirm(){busy.value=true;error.value='';try{for(const source of suggestions.value.filter(x=>selected.value.includes(x.url)))await api(wp('/sources'),{method:'POST',body:{...source,respect_robots:true}});state.workspace=await api(wp('/profile'),{method:'PUT',body:{...payload(),reviewed:true}});await loadWorkspaces(state.workspace.id);await loadData();router.push('/overview');notify(t('Company context confirmed. Your workspace is ready.','Контекст компании подтверждён. Пространство готово к работе.'))}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div :class="editing?'company-edit':'onboarding-page'"><div class="onboard-heading"><span class="eyebrow">{{editing?t('MAKE THE CONTEXT YOURS','ВАШ КОНТЕКСТ — ТОЧНЕЕ ВЫВОДЫ'):t('A LITTLE CONTEXT GOES A LONG WAY','КОНТЕКСТ МЕНЯЕТ КАЧЕСТВО РЕШЕНИЙ')}}</span><h1>{{editing?t('Your company, in focus.','Ваша компания в фокусе.'):t('Let’s understand your business.','Познакомимся с вашим бизнесом.')}}</h1><p>{{t('Tell us what shapes your decisions. You review every detail before monitoring begins.','Расскажите, что влияет на решения. Вы проверите все данные до начала мониторинга.')}}</p></div>
<div class="onboard-stepper"><div v-for="(label,i) in [t('Your website','Ваш сайт'),t('Business context','Бизнес-контекст'),t('Review & connect','Проверка и запуск')]" :key="i" :class="{active:step===i+1,done:step>i+1}"><span><Icon v-if="step>i+1" name="Check" :size="15"/><template v-else>{{i+1}}</template></span>{{label}}<i v-if="i<2"></i></div></div>
<div v-if="error" class="notice error-notice" role="alert"><Icon name="AlertCircle" :size="18"/><span>{{error}}</span></div>
<section v-if="step===1" class="onboard-grid"><div class="card onboard-form"><span class="form-section-icon"><Icon name="Globe2" :size="25"/></span><h2>{{t('Start with your company website','Начните с сайта компании')}}</h2><p class="muted">{{t('We’ll draft a profile from your public website. Financial details and business exposures stay yours to confirm.','Мы подготовим профиль по публичному сайту. Финансовые данные и факторы влияния вы подтвердите сами.')}}</p><form @submit.prevent="discover()" class="form-stack"><label>{{t('Company website','Сайт компании')}}<input v-model="form.website" type="text" inputmode="url" placeholder="https://your-company.com" required :disabled="busy"></label><button class="btn primary large-btn full" :disabled="busy"><Icon :name="busy?'LoaderCircle':'Sparkles'" :class="{spin:busy}" :size="17"/>{{busy?t('Getting to know your company…','Изучаем вашу компанию…'):t('Build my company profile','Создать профиль компании')}}<Icon v-if="!busy" name="ArrowRight" :size="17"/></button></form><div v-if="job&&busy" class="onboard-progress"><div class="progress-track"><i :style="{width:Math.max(5,job.progress)+'%'}"></i></div><span class="small muted">{{job.steps?.at(-1)?.name?.replaceAll('_',' ')}} · {{job.progress}}%</span></div><button class="text-link center mt-sm" :disabled="busy||!form.website" @click="discover(true)">{{t('I’ll enter the details myself','Введу данные самостоятельно')}}</button></div><aside class="onboard-help"><span class="eyebrow">{{t('WHAT WE LOOK FOR','НА ЧТО ОБРАТИМ ВНИМАНИЕ')}}</span><div v-for="s in [{icon:'Building2',title:t('What your company does','Чем занимается компания'),body:t('Industry, activities and operating regions.','Отрасль, деятельность и регионы.')},{icon:'Focus',title:t('What matters to your decisions','Что важно для ваших решений'),body:t('Your role, priorities and business exposures.','Роль, приоритеты и факторы влияния.')},{icon:'ShieldCheck',title:t('What we don’t assume','Чего мы не предполагаем'),body:t('Revenue, debt and market share are never guessed. You fill the gaps.','Мы не угадываем выручку, долги и долю рынка. Пробелы заполняете вы.')} ]" :key="s.title"><Icon :name="s.icon" :size="21"/><h3>{{s.title}}</h3><p>{{s.body}}</p></div></aside></section>
<section v-else-if="step===2" class="card context-form"><div class="card-heading"><div><h2>{{t('Put your business in context','Добавьте бизнес-контекст')}}</h2><p>{{t('Confirm the draft and add the details a website cannot tell us.','Проверьте профиль и добавьте то, чего нет на сайте.')}}</p></div><span class="badge neutral">{{t('Editable draft','Редактируемый профиль')}}</span></div><form @submit.prevent="review" class="form-stack"><div class="form-grid"><label>{{t('Company name','Название компании')}}<input v-model="form.name" required maxlength="150"></label><label>{{t('Industry','Отрасль')}}<input v-model="form.industry" required :placeholder="t('e.g. Education technology','Например: образовательные технологии')"></label><label class="span-2">{{t('What the company does','Чем занимается компания')}}<textarea v-model="form.description" rows="3" :placeholder="t('Products, services and who you serve','Продукты, услуги и ваши клиенты')"></textarea></label><label>{{t('Customer segments','Клиентские сегменты')}}<input v-model="form.customers" :placeholder="t('e.g. Teachers, schools, corporate clients','Например: преподаватели, школы, корпоративные клиенты')"></label><label>{{t('Operating regions','Регионы присутствия')}}<input v-model="form.regions" :placeholder="t('e.g. Russia, United States','Например: Россия, США')"></label><label>{{t('Your decision role','Ваша бизнес-роль')}}<select v-model="form.decision_role"><option v-for="r in roles" :key="r.id" :value="r.id">{{r.label}}</option></select></label></div><div class="form-divider"></div><h3>{{t('What could move your business?','Что может повлиять на ваш бизнес?')}}</h3><p class="small muted no-margin">{{t('Select confirmed exposures. These shape relevance and interpretation.','Выберите подтверждённые факторы. Они влияют на отбор событий и выводы.')}}</p><div class="exposure-grid"><label v-for="o in exposureOptions" :key="o.id" :class="{selected:form.exposures.includes(o.id)}"><input v-model="form.exposures" type="checkbox" :value="o.id"><span>{{o.label}}</span></label></div><div v-if="form.exposures.filter(x=>!exposureOptions.some(o=>o.id===x)).length" class="chips"><span v-for="e in form.exposures.filter(x=>!exposureOptions.some(o=>o.id===x))" :key="e" class="chip">{{e}}<button type="button" @click="form.exposures=form.exposures.filter(x=>x!==e)" :aria-label="t('Remove exposure','Удалить фактор')"><Icon name="X" :size="12"/></button></span></div><label>{{t('Other exposures or contract sensitivities','Другие факторы или чувствительные условия договоров')}}<input v-model="custom" :placeholder="t('e.g. USD cloud bills, seasonal demand','Например: облако в USD, сезонный спрос')"></label><div class="form-grid"><label>{{t('Current priorities','Текущие приоритеты')}}<textarea v-model="form.priorities" rows="2" :placeholder="t('e.g. Margin, retention, refinancing','Например: маржа, удержание, рефинансирование')"></textarea></label><label>{{t('Key counterparties / suppliers','Ключевые контрагенты / поставщики')}}<textarea v-model="form.counterparties" rows="2" :placeholder="t('Names or categories, separated by commas','Названия или категории через запятую')"></textarea></label><label>{{t('Competitors to watch','Конкуренты для мониторинга')}}<input v-model="form.competitors" :placeholder="t('Optional · company names','Необязательно · названия компаний')"></label><label>{{t('Annual revenue / scale','Годовая выручка / масштаб')}}<input v-model="form.revenue" :placeholder="t('Unknown is fine','Можно оставить неизвестной')"></label></div><div class="notice"><Icon name="Info" :size="17"/>{{t('Missing information stays unknown. You can enrich the profile later with the case client CSV and payment links.','Недостающие данные остаются неизвестными. Позже можно добавить CSV клиентов и платёжные связи из кейса.')}}</div><div class="form-actions"><button type="button" class="btn ghost" @click="step=1"><Icon name="ArrowLeft" :size="16"/>{{t('Website','Сайт')}}</button><button class="btn primary" :disabled="busy"><Icon v-if="busy" name="LoaderCircle" class="spin" :size="17"/>{{t('Review profile & sources','Проверить профиль и источники')}}<Icon name="ArrowRight" :size="17"/></button></div></form></section>
<section v-else class="review-grid"><div class="card"><div class="card-heading"><h2>{{t('Your company profile','Профиль компании')}}</h2><button class="text-link" @click="step=2"><Icon name="Pencil" :size="14"/>{{t('Edit','Изменить')}}</button></div><div class="company-review-header"><span class="company-mark">{{form.name.slice(0,1)}}</span><div><h3>{{form.name}}</h3><span class="muted">{{form.industry}}</span></div></div><p class="review-description">{{form.description}}</p><dl class="detail-list"><dt>{{t('Website','Сайт')}}</dt><dd>{{form.website}}</dd><dt>{{t('Regions','Регионы')}}</dt><dd>{{form.regions||t('Not specified','Не указаны')}}</dd><dt>{{t('Priorities','Приоритеты')}}</dt><dd>{{form.priorities||t('Not specified','Не указаны')}}</dd><dt>{{t('Revenue','Выручка')}}</dt><dd>{{form.revenue||t('Not disclosed','Не раскрыта')}}</dd></dl><h4>{{t('Business exposures','Факторы влияния')}}</h4><div class="chips"><span v-for="x in payload().exposures" :key="x" class="chip">{{exposureOptions.find(o=>o.id===x)?.label||x}}</span></div><div class="review-evidence" v-if="state.workspace?.profile.evidence?.length"><Icon name="Link2" :size="15"/><span>{{state.workspace?.profile.synthetic_company_id?t('Based on reviewed case data. Public company identity is unconfirmed.','На основе данных кейса. Публичная идентичность компании не установлена.'):state.workspace?.profile.evidence?.length?t('Drafted from your public website. Confirmed by you.','Подготовлено по публичному сайту. Подтверждается вами.'):t('Entered by you. Reviewed for monitoring.','Введено вами. Проверено для мониторинга.')}}</span></div></div><div class="card"><div class="card-heading"><div><h2>{{t('Your monitoring setup','Настройки мониторинга')}}</h2><p>{{t('Publishers discovered for your markets and checked before connecting.','Источники для ваших рынков, проверенные до подключения.')}}</p></div></div><label class="form-label">{{t('Monitoring topics & keywords','Темы и ключи мониторинга')}}<textarea v-model="form.keywords" rows="3" :placeholder="t('Separate topics with commas','Разделяйте темы запятыми')"></textarea></label><h4>{{t('Suggested sources','Предлагаемые источники')}}</h4><p v-if="sourceStatus" class="notice small" role="status">{{sourceStatus}}</p><button type="button" class="btn secondary small-btn mb-sm" :disabled="busy" @click="findSources"><Icon :name="busy?'LoaderCircle':'Search'" :class="{spin:busy}" :size="15"/>{{t('Search again','Найти источники заново')}}</button><label v-for="s in suggestions" :key="s.url" class="suggestion-source"><input type="checkbox" v-model="selected" :value="s.url"><span><strong>{{s.name}}</strong><small>{{l(s.reason)}}</small></span><Icon name="Radio" :size="17"/></label><div class="notice mt-sm"><span class="bank-mark small-mark">A</span><span>{{t('Alfa-Bank case research is already available in your evidence library. It will be retrieved when relevant.','Обзоры Альфа-Банка из кейса уже доступны в библиотеке и будут использованы, если релевантны событию.')}}</span></div><button class="btn primary full large-btn mt-lg" :disabled="busy" @click="confirm"><Icon :name="busy?'LoaderCircle':'Check'" :class="{spin:busy}" :size="18"/>{{t('Confirm & open my workspace','Подтвердить и открыть пространство')}}</button><p class="small muted center">{{t('You can review or change this context at any time.','Вы можете изменить контекст в любой момент.')}}</p></div></section></div></template>
